d',$event['id']).hidden('version',input($_POST,'action')==='gema-link-invoice'&&input($_POST,'id')===$event['id']?input($_POST,'version'):$gema['version']) ?><label><?= e($gemaText('Bereits in Finanzen vorhandene Rechnung')) ?><select class="form-control" name="entry_id" required><option value=""><?= e($gemaText('Bitte auswählen')) ?></option><?php foreach($finance->entries(['kind'=>'expense']) as $invoice):if(in_array($invoice['payment_state'],['cancelled','reversed'],true))continue; ?><option value="<?= e($invoice['id']) ?>" <?= input($_POST,'action')==='gema-link-invoice'&&input($_POST,'id')===$event['id']&&input($_POST,'entry_id')===$invoice['id']?'selected':'' ?>><?= e($invoice['display_number'].' · '.$invoice['description'].' · '.euro((int)$invoice['amount_cents'])) ?></option><?php endforeach ?></select></label><button class="btn btn-solid theme-primary"><?= e($gemaText('Rechnung zuordnen')) ?></button></form><?php endif ?></section></div><?php endif ?>
